import{z as o,x as s,o as A,c as d,q as l,j as n,D as a,d as t,s as i,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"低精度推理的误差预算","description":"","frontmatter":{"title":"低精度推理的误差预算","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/num-inference-error-budget.md","filePath":"llm/num-inference-error-budget.md","lastUpdated":1791063341000}'),p={name:"llm/num-inference-error-budget.md"};function m(F,E,u,h,P,f){const r=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=l('<h1 id="低精度推理的误差预算" tabindex="-1">低精度推理的误差预算 <a class="header-anchor" href="#低精度推理的误差预算" aria-label="Permalink to &quot;低精度推理的误差预算&quot;">​</a></h1><div class="epigraph"><p>预算思维把「能不能量化」变成「把误差花在哪」：权重、KV、激活、注意力核各有价目表，任务指标是唯一收银台。</p><footer>—— 据 Frantar et al., 2022（GPTQ）与 KV 量化文献的误差口径整理</footer></div><p><a href="/llm/num-sparse-training">上一课</a>收掉稀疏的数值账，训练侧的七课到此把「怎么把数算稳」写完；本课转到部署侧。低精度推理的各零件都已单独写过：权重的 <a href="/llm/gptq">GPTQ</a>、KV 的两档在 <a href="/llm/kv-quant-int8-int4">KV 量化：INT8 与 INT4</a>、逐层敏感度与 bit 背包在 <a href="/llm/mixed-precision-search">混合精度搜索</a>、低精度注意力核在 <a href="/llm/ak-quantized-attention-kernel">低精度注意力的内核</a>。本课不重复任何一件零件，只做装配：把每个部件花的误差写进同一张预算表，规定怎么加总、拿什么验收。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次低精度前向里至少四笔误差同时发生：权重的量化误差（PTQ 校准或 QAT 冻结）、KV 缓存的量化误差（在线追加、随上下文长度累积）、激活与注意力的低精度计算误差（随实现与序列位置变）、采样前的 logits 扰动。它们不同质：权重误差是<strong>固定偏置</strong>——同一权重每次前向犯同样的错；KV 误差是<strong>累积过程</strong>——错误的历史持续参与后续注意力；核误差近似<strong>每次独立的噪声</strong>。加总因此不是算术相加：logit 扰动过 softmax 是非线性的，PPL 对几笔误差的敏感度也不一样——KV 的误差在长上下文上先爆，短文本 PPL 几乎不动。</p><p>预算表的真正问题是分配：在总误差上限内，哪个部件多拿比特、哪个部件少拿，依据是什么。</p><p><span class="marginnote">直觉类比：权重误差像鞋里固定的石子（每步都偏同一个方向），KV 误差像记错的地图（错的历史一直带你走），核误差像手抖（每次抖得不一样）。三种病用药不同：石子换鞋垫（校准），地图要修正（重写缓存），手抖靠稳（平均）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算表三列起步：部件（权重 / KV / 激活 / 注意力核 / 最终 logits）、格式与粒度、误差代理。误差代理要便宜且可比：层输出 MSE、校准集上的交叉熵增量、或 logits 层与宽基线的 KL。流程四步：先跑宽基线定上限；逐部件单独降级，记录<strong>边际误差</strong>（该部件从 8-bit 到 4-bit 独自增加多少）；按敏感度把比特预算花出去——lm_head、首层、KV 的键天然是高敏感户，与 <a href="/llm/mixed-precision-search">混合精度搜索</a> 的背包是同一算法；最后在任务指标上整表验收。</p><p><span class="marginnote">数字实例：lm_head 从 8-bit 降到 4-bit，短文本 PPL 单独涨 0.05；KV 同样操作只涨 0.01——先别把 KV 砍到 4-bit：128K 检索上它的账完全不同。边际误差必须连同「在哪类任务上量的」一起报告，否则是没单位的数据。</span></p>',10)),(A(),n(B,null,{default:a(()=>[i(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E5%AE%BD%E5%9F%BA%E7%BA%BF%EF%BC%9A%E5%AE%9A%E8%AF%AF%E5%B7%AE%E4%B8%8A%E9%99%90%22%5D%20--%3E%20ABL%5B%22%E9%80%90%E9%83%A8%E4%BB%B6%E9%99%8D%E7%BA%A7%EF%BC%9A%E8%AE%B0%E8%BE%B9%E9%99%85%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20ABL%20--%3E%20KNAP%5B%22%E6%8C%89%E6%95%8F%E6%84%9F%E5%BA%A6%E5%88%86%E6%AF%94%E7%89%B9%EF%BC%9A%E6%95%8F%E6%84%9F%E6%88%B7%E4%B9%B0%E7%B2%BE%E5%BA%A6%22%5D%0A%20%20KNAP%20--%3E%20INT%5B%22%E6%95%B4%E8%A1%A8%E7%BB%84%E5%90%88%EF%BC%9A%E6%9F%A5%E4%BA%A4%E4%BA%92%E9%A1%B9%22%5D%0A%20%20INT%20--%3E%20TASK%5B%22%E4%BB%BB%E5%8A%A1%E9%AA%8C%E6%94%B6%EF%BC%9A%E5%88%86%E8%83%BD%E5%8A%9B%E6%8C%87%E6%A0%87%22%5D%0A%20%20TASK%20--%3E%7C%E8%B6%85%E9%A2%84%E7%AE%97%7C%20RES%5B%22%E8%B5%8E%E5%9B%9E%EF%BC%9A%E6%95%8F%E6%84%9F%E9%83%A8%E4%BB%B6%E6%8F%90%E6%A1%A3%E6%88%96%E8%92%B8%E9%A6%8F%22%5D%0A%20%20TASK%20--%3E%7C%E8%BE%BE%E6%A0%87%7C%20SHIP%5B%22%E5%8F%91%E8%B4%A7%EF%BC%9A%E9%A2%84%E7%AE%97%E8%A1%A8%E9%9A%8F%E6%A8%A1%E5%9E%8B%E5%BD%92%E6%A1%A3%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"验收的分账规则：短文本 PPL 是最钝的收银台，长上下文针检索、代码、数学各自对误差的敏感谱不同，整表验收必须分能力做，且对照运行级方差（run-to-run 噪声）——低于基线噪声的误差免票。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"预算能分配的机制根据是一阶可加性：各部件的扰动对 logits 的贡献在一阶近似下可加，残差网络的跨层补偿是一阶之外的美好意外。这解释了两个现象：为什么逐部件测得的边际误差在整表组合后常略好于相加（补偿），偶尔显著更差（某两笔误差在同一坐标上同号叠加——交互项，必须整表复测）；为什么 PPL 会骗——PPL 是对数尺度上的平均，把少数任务上的大误差摊平，预算表要留一列「分位数误差」而不是只看均值。KV 误差的累积性让它的预算随上下文长度重新定价：8-bit 在 4K 上下文免票，128K 上要重验，这正是 KV 课「评估看长上下文任务」的预算表版本。",-1)),(A(),n(B,null,{default:a(()=>[i(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20E%5B%22KV%20%E5%8D%95%E6%AD%A5%E9%87%8F%E5%8C%96%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20H%5B%22%E5%86%99%E8%BF%9B%E5%8E%86%E5%8F%B2%E7%BC%93%E5%AD%98%22%5D%0A%20%20H%20--%3E%20ATT%5B%22%E5%90%8E%E7%BB%AD%E6%AF%8F%E6%AD%A5%E6%B3%A8%E6%84%8F%E5%8A%9B%E9%83%BD%E8%AF%BB%E5%88%B0%E5%AE%83%22%5D%0A%20%20ATT%20--%3E%20ACC%5B%22%E8%AF%AF%E5%B7%AE%E9%9A%8F%E4%B8%8A%E4%B8%8B%E6%96%87%E7%B4%AF%E7%A7%AF%22%5D%0A%20%20ACC%20--%3E%20R%5B%224K%20%E5%85%8D%E7%A5%A8%E7%9A%84%208bit%20%E5%88%B0%20128K%20%E8%A6%81%E9%87%8D%E9%AA%8C%E9%87%8D%E6%96%B0%E5%AE%9A%E4%BB%B7%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p>这张图回答「为什么 KV 的预算要按上下文长度重新定价」：KV 的错不是一次性噪声，而是被写进历史、被后续每一步注意力反复消费的偏置——短文本上免票的格式，长上下文上必须整表重验。</p><p><span class="marginnote">预算表是负载相关的：decode 阶段 M 小、KV 主导带宽，prefill 阶段权重与激活主导计算——同一张表在两类负载上的敏感度排序可以不同，发货前各跑一遍。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>预算表是模型的、负载的，不是行业的：换基座换负载要重测，别引用别人的表。超预算部件的赎回顺序有讲究：先提档敏感部件（便宜、确定），蒸馏是重武器（贵、能赎回更深误差）。采样的温度会放大或掩盖 logits 扰动——预算表按生产采温验收，不按贪婪。最后，预算表随模型归档：它是第九课跨硬件验收与后续迭代的基线，丢了表，回归就只剩体感。</p><p><span class="marginnote">常见误区：把 0.001 的 PPL 改善当胜利。同配置重跑两次的 run-to-run 噪声可能就有 0.01——小于噪声带的差异是抽奖不是效应，验收之前先测一遍自己的噪声地板。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四笔误差不同质：权重是固定偏置，KV 是累积过程，核是独立噪声；加总有交互项。</li><li>预算表三列：部件、格式粒度、便宜可比的误差代理；逐部件记边际误差再整表复测。</li><li>敏感户（lm_head、首层、KV 键）先买精度；分配是混合精度搜索的背包。</li><li>验收分能力、按生产采温、对照运行方差；短文本 PPL 是最钝的收银台。</li><li>预算表随模型归档，是跨硬件与迭代回归的基线。</li><li>出处：Frantar et al., 2022（GPTQ）的误差口径；KV 量化与本课程前七课的记账框架。</li></ul>',7))])}const g=o(p,[["render",m]]);export{T as __pageData,g as default};
